#!/usr/bin/env node
// consort-spike: cut / list / delete throwaway spike branches.
//
//   consort-spike cut --slug <s> --instance <i> [--for <feature>]
//                          [--parent <branch>] [--ttl <t>] [--project-dir <d>] [--json]
//   consort-spike list [--project-dir <d>] [--json]
//   consort-spike delete --slug <s> --instance <i> [--keep-branch] [--project-dir <d>]
//
// A spike is throwaway exploration OUTSIDE the TDD loop: it gets its own paired
// Lakebase branch (spike/<slug> by convention), and its notes.md carries the
// learning forward into a feature's design-spec gate (via `--for <feature>`,
// which tags the notes). Code is never promoted from a spike, only notes.
//
// Exit codes: 0 ok, 2 bad args, 7 substrate failure.

import * as path from "node:path";
import { resolveConsortDir } from "../../consort/config/consort-paths.js";

import { isCliEntry } from "@databricks-solutions/lakebase-scm-utils/util";
import { readEnvVar } from "@databricks-solutions/lakebase-scm-utils/lakebase";
import { cutSpike, listSpikes, deleteSpike, spikeNotes } from "../../consort/experiment/spike.js";
import { beginTelemetryRun } from "../../consort/telemetry/with-telemetry.js";

interface ParsedArgs {
  slug?: string;
  forFeature?: string;
  parent?: string;
  ttl?: string;
  instance?: string;
  host?: string;
  projectDir?: string;
  consortDir?: string;
  keepBranch?: boolean;
  purgeNotes?: boolean;
  json?: boolean;
}

function parseArgs(argv: string[]): ParsedArgs {
  const out: ParsedArgs = {};
  for (let i = 0; i < argv.length; i++) {
    switch (argv[i]) {
      case "--slug": out.slug = argv[++i]; break;
      case "--for": out.forFeature = argv[++i]; break;
      case "--parent": out.parent = argv[++i]; break;
      case "--ttl": out.ttl = argv[++i]; break;
      case "--instance": out.instance = argv[++i]; break;
      case "--host": out.host = argv[++i]; break;
      case "--project-dir": out.projectDir = argv[++i]; break;
      case "--tdd-dir": out.consortDir = argv[++i]; break;
      case "--keep-branch": out.keepBranch = true; break;
      case "--purge-notes": out.purgeNotes = true; break;
      case "--json": out.json = true; break;
    }
  }
  return out;
}

const HELP = `consort-spike (throwaway spike branches)

Usage:
  consort-spike cut --slug <s> [--instance <i>] [--for <feature>] [--parent <b>] [--ttl <t>] [--project-dir <d>] [--json]
  consort-spike list [--project-dir <d>] [--json]
  consort-spike delete --slug <s> [--instance <i>] [--keep-branch] [--purge-notes] [--project-dir <d>]

A spike is throwaway exploration outside the TDD loop. --for <feature> tags the
notes so the learning carries forward into that feature's design-spec gate.

--instance / --host default from the project .env (LAKEBASE_PROJECT_ID / DATABRICKS_HOST),
so from inside a scaffolded project you can omit them. On delete, the notes are KEPT by
default (the learning survives the branch teardown); pass --purge-notes to also remove the
spike's .consort/spikes/<slug>/ dir for a full cleanup.
`;

function tddDirFor(args: ParsedArgs): string {
  return args.consortDir ?? resolveConsortDir(args.projectDir ?? ".");
}

export async function runSpikeCli(argv: string[]): Promise<number> {
  const sub = argv[0];
  if (!sub || sub === "-h" || sub === "--help") {
    process.stdout.write(HELP);
    return sub ? 0 : 2;
  }
  const args = parseArgs(argv.slice(1));
  const consortDir = tddDirFor(args);

  // Pair with create-project: default the instance + host from the project .env
  // (LAKEBASE_PROJECT_ID / DATABRICKS_HOST) so a spike can be cut / torn down from
  // inside a scaffolded project without re-typing them. Explicit flags win.
  const envPath = path.join(args.projectDir ?? process.cwd(), ".env");
  if (!args.instance) args.instance = readEnvVar(envPath, "LAKEBASE_PROJECT_ID");
  if (!args.host) args.host = readEnvVar(envPath, "DATABRICKS_HOST");

  // Every user-invoked command emits telemetry, regardless of which bin serves it. A
  // spike (cut/delete) is not a role drive, so it emits a root `consort.run` (command
  // "spike") with zero gate spans, flushed by the detached sender at the end. list/help
  // are reads (telemetry undefined => finishTel is a no-op). Never blocks the CLI.
  const telemetry =
    sub === "cut" || sub === "delete"
      ? beginTelemetryRun({ command: "spike", onNotice: (m) => process.stderr.write(m) })
      : undefined;
  const finishTel = (rc: number): number => {
    try {
      telemetry?.finish({ outcome: rc === 0 ? "completed" : "error", exit_code: rc });
    } catch {
      /* telemetry never affects the CLI */
    }
    return rc;
  };
  try {
    if (sub === "cut") {
      if (!args.slug || !args.instance) {
        process.stderr.write("Error: cut requires --slug and --instance.\n");
        return finishTel(2);
      }
      const rec = await cutSpike({
        consortDir,
        projectDir: args.projectDir ?? process.cwd(),
        spikeSlug: args.slug,
        branch: `spike/${args.slug}`,
        parentBranch: args.parent,
        ttl: args.ttl,
        notes: spikeNotes(args.slug, args.forFeature),
        instance: args.instance,
        host: args.host,
      });
      process.stdout.write(
        args.json
          ? `${JSON.stringify(rec)}\n`
          : `consort-spike: cut ${rec.spike_slug} (branch ${rec.branch_id})${args.forFeature ? ` for ${args.forFeature}` : ""}\n`,
      );
      return finishTel(0);
    }

    if (sub === "list") {
      const spikes = listSpikes(consortDir);
      process.stdout.write(
        args.json
          ? `${JSON.stringify(spikes)}\n`
          : (spikes.length
              ? spikes.map((s) => `${s.spike_slug}\t${s.branch_id}`).join("\n") + "\n"
              : "(no spikes)\n"),
      );
      return finishTel(0);
    }

    if (sub === "delete") {
      if (!args.slug || (!args.keepBranch && !args.instance)) {
        process.stderr.write("Error: delete requires --slug (and --instance unless --keep-branch).\n");
        return finishTel(2);
      }
      await deleteSpike({
        consortDir,
        projectDir: args.projectDir ?? process.cwd(),
        spikeSlug: args.slug,
        deleteBranchToo: !args.keepBranch,
        purgeNotes: args.purgeNotes,
        instance: args.instance ?? "",
        host: args.host,
      });
      const tail = [args.keepBranch ? "branch kept" : null, args.purgeNotes ? "notes purged" : "notes kept"]
        .filter(Boolean)
        .join(", ");
      process.stdout.write(`consort-spike: deleted ${args.slug} (${tail})\n`);
      return finishTel(0);
    }

    process.stderr.write(`Error: unknown subcommand "${sub}".\n\n${HELP}`);
    return finishTel(2);
  } catch (e) {
    process.stderr.write(`consort-spike: ${e instanceof Error ? e.message : String(e)}\n`);
    return finishTel(7);
  }
}

if (isCliEntry(import.meta.url)) {
  runSpikeCli(process.argv.slice(2)).then((code) => process.exit(code));
}
